// 示例：四名验证者下，竞争候选通过投票胜出本地提议。
//
// 流程：建立节点并提交两笔交易 -> 本地提议打包两笔 -> 登记只含高费交易的
// 竞争候选 -> 一名验证者投本地提议、改投被拒 -> 三名验证者依次投竞争候选，
// 两票不够、第三票确认 -> 查询刚结束的轮次与两笔交易的最终状态。
//
// 运行：go run ./examples/contending-candidate
package main

import (
	"bytes"
	"crypto/ed25519"
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/bengzyyys/consensus-lab/consensus"
)

// check 处理正常调用的错误：任何非预期失败都直接终止演示。
func check(err error) {
	if err != nil {
		log.Fatalf("unexpected error: %v", err)
	}
}

// demoKey 由固定字节派生演示密钥，使示例输出可复现；
// 真实应用应使用 crypto/rand 随机生成并妥善保管私钥。
func demoKey(b byte) ed25519.PrivateKey {
	return ed25519.NewKeyFromSeed(bytes.Repeat([]byte{b}, ed25519.SeedSize))
}

// short 截断长标识便于对照阅读；标识本身均来自实际返回值。
func short(id string) string {
	if len(id) > 16 {
		return id[:16] + "…"
	}
	return id
}

func main() {
	log.SetFlags(0)

	// 四名验证者与两个互不相同的发送账户。
	validatorKeys := make([]ed25519.PrivateKey, 4)
	validators := make([][]byte, 4)
	for i := range validatorKeys {
		validatorKeys[i] = demoKey(byte(i + 1))
		validators[i] = append([]byte(nil), validatorKeys[i].Public().(ed25519.PublicKey)...)
	}
	aliceKey := demoKey(0xa1)
	bobKey := demoKey(0xb0)
	alicePub := aliceKey.Public().(ed25519.PublicKey)
	bobPub := bobKey.Public().(ed25519.PublicKey)

	// 在新的状态目录建立节点：固定种子、四名验证者、单块最多两笔交易。
	dir, err := os.MkdirTemp("", "consensus-demo-*")
	check(err)
	defer os.RemoveAll(dir)

	n, err := consensus.New(dir, consensus.Config{
		Seed:           []byte("contending-candidate-demo"),
		Validators:     validators,
		MaxTxsPerBlock: 2,
	})
	check(err)
	fmt.Printf("节点已建立：轮次 %d，单块上限 2，验证者 4 名（确认需严格超过 2/3，即至少 3 票）\n",
		n.CurrentRound())

	// 提交两笔交易：分属 Alice 与 Bob，序号均为 1，到期轮次 100 在演示期间不会到达，
	// 费用分别为 20 与 10。
	txAlice := consensus.NewTransaction(aliceKey, 1, []byte("alice: fee 20"), 20, 100)
	txBob := consensus.NewTransaction(bobKey, 1, []byte("bob: fee 10"), 10, 100)
	subAlice, err := n.Submit(txAlice)
	check(err)
	subBob, err := n.Submit(txBob)
	check(err)
	fmt.Printf("已提交 Alice 交易（费用 20）：%s\n", subAlice.TxID)
	fmt.Printf("已提交 Bob 交易（费用 10）：%s\n", subBob.TxID)

	// 本地提议：打包规则按费用从高到低选取各账户下一条可确认交易，
	// 上限两笔，故两笔都入选且费用 20 的排在前面。
	proposal, err := n.Propose()
	check(err)
	fmt.Printf("\n本地提议（轮次 %d）：区块 %s\n", proposal.Round, proposal.BlockID)
	for i, id := range proposal.TxIDs {
		fmt.Printf("  打包顺序 %d：%s\n", i+1, id)
	}

	// 登记竞争候选：只包含费用 20 的那笔交易，与本地提议同轮竞争。
	reg, err := n.RegisterCandidate(proposal.Round, []string{subAlice.TxID})
	check(err)
	fmt.Printf("竞争候选（仅含 Alice 交易）：区块 %s（新登记=%v）\n", reg.BlockID, !reg.Existing)

	// 保存轮次值：确认之后查询刚结束的轮次要用它。
	round := proposal.Round

	// 验证者 0 投给本地提议。
	vr, err := n.Vote(validators[0], round, proposal.BlockID)
	check(err)
	fmt.Printf("\n验证者 0 投给本地提议：计入=%v，确认=%v\n", vr.Counted, vr.Confirmed)

	// 验证者 1 投给竞争候选（第 1 票）。
	vr, err = n.Vote(validators[1], round, reg.BlockID)
	check(err)
	fmt.Printf("验证者 1 投给竞争候选：计入=%v，确认=%v\n", vr.Counted, vr.Confirmed)

	// 验证者 0 在确认前尝试改投竞争候选：预期被 already-voted 拒绝，原票保留。
	// 这是本演示中唯一预期出现的错误，须与其他失败区分开。
	_, err = n.Vote(validators[0], round, reg.BlockID)
	var rej *consensus.RejectError
	switch {
	case errors.As(err, &rej) && rej.Reason == consensus.ReasonAlreadyVoted:
		fmt.Printf("验证者 0 改投被拒绝（预期）：%v\n", rej)
	case err != nil:
		log.Fatalf("改投出现预期外的错误：%v", err)
	default:
		log.Fatal("改投被接受，违反每位验证者一轮一票的规则")
	}

	// 验证者 2 投给竞争候选（第 2 票）：四人名单要求严格超过 2/3，2 票仍不够。
	vr, err = n.Vote(validators[2], round, reg.BlockID)
	check(err)
	fmt.Printf("验证者 2 投给竞争候选：计入=%v，确认=%v（2 票未达 3 票门槛）\n", vr.Counted, vr.Confirmed)

	rc, err := n.Candidates(round)
	check(err)
	fmt.Printf("此时轮次 %d 仍未决出：\n", round)
	for _, c := range rc.Candidates {
		fmt.Printf("  候选 %s（本地=%v）结果=%s，票数=%d\n", short(c.BlockID), c.Local, c.Result, len(c.Voters))
	}

	// 验证者 3 投出第 3 票：严格超过 4 的 2/3，竞争候选立即确认。
	vr, err = n.Vote(validators[3], round, reg.BlockID)
	check(err)
	if !vr.Confirmed || vr.Block == nil {
		log.Fatal("第 3 票应使竞争候选立即确认")
	}
	fmt.Printf("验证者 3 投给竞争候选：计入=%v，确认=%v，新区块高度 %d\n", vr.Counted, vr.Confirmed, vr.Block.Height)

	// 用保存的轮次值查询刚结束的轮次：竞争候选胜出、本地提议落选，各自投票者保留。
	rc, err = n.Candidates(round)
	check(err)
	fmt.Printf("\n轮次 %d 已决出（节点当前轮次 %d）：\n", round, n.CurrentRound())
	for _, c := range rc.Candidates {
		fmt.Printf("  候选 %s（本地=%v）结果=%s，投票者：\n", short(c.BlockID), c.Local, c.Result)
		for _, v := range c.Voters {
			fmt.Printf("    %x\n", v)
		}
	}

	// 费用 20 的交易随胜出块确认；其账户已确认序号推进为 1。
	infoAlice, err := n.Tx(subAlice.TxID)
	check(err)
	fmt.Printf("\nAlice 交易：状态=%s，所在块高度=%d，区块=%s\n",
		infoAlice.Status, infoAlice.BlockHeight, infoAlice.BlockID)
	accAlice := n.Account(alicePub)
	fmt.Printf("Alice 账户：已确认序号=%d，待处理交易=%d 笔\n",
		accAlice.ConfirmedSequence, len(accAlice.Pending))

	// 仅被本地提议引用的 Bob 交易回到排队；其账户已确认序号仍为 0，
	// 账户查询显示它在等待打包。
	infoBob, err := n.Tx(subBob.TxID)
	check(err)
	fmt.Printf("Bob 交易：状态=%s\n", infoBob.Status)
	accBob := n.Account(bobPub)
	fmt.Printf("Bob 账户：已确认序号=%d\n", accBob.ConfirmedSequence)
	for _, p := range accBob.Pending {
		fmt.Printf("  待处理 %s：状态=%s，说明=%s\n", short(p.ID), p.Status, p.Note)
	}

	// 落选的本地提议不会生成另一条确认历史：确认历史只有胜出块一条。
	latest, ok := n.LatestBlock()
	if !ok {
		log.Fatal("应已有确认块")
	}
	fmt.Printf("\n确认历史共 %d 条，最新块高度 %d、区块 %s（即胜出的竞争候选）\n",
		n.Height(), latest.Height, latest.ID)
}

// Package consensus 是本地共识与交易池仿真。
//
// 典型流程：
//
//	n, err := consensus.New(dir, consensus.Config{
//	    Seed: seed, Validators: validatorKeys, MaxTxsPerBlock: 10,
//	})
//	tx := consensus.NewTransaction(priv, 1, []byte("hello"), 5, 100)
//	if _, err := n.Submit(tx); err != nil { … }
//	p, err := n.Propose()                  // 每轮唯一本地提议，重复调用返回同一结果
//	// 本地提议产生后、确认前，可按交易顺序登记其他竞争候选：
//	r, err := n.RegisterCandidate(p.Round, []string{tx.ID()})
//	n.Vote(validator, p.Round, p.BlockID)  // 可投给任一已登记候选，票数严格超过 2/3 立即确认
//	rc, _ := n.Candidates(p.Round)         // 查看本轮候选、投票者、结果与未投票验证者
//
// 同一轮可有多个候选块竞争：候选使用当前轮次与下一高度，接在最新确认块之后；
// 每位验证者一轮只能选择一个候选，胜出候选立即确认，其他候选落选，其独有交易回池。
//
// 停止后用 Open(dir) 恢复轮次、交易池、未决候选、每人已投的选择、票数、确认历史、
// 池容量与淘汰记录。版本 1、2 的旧状态目录仍可打开：未保存容量时按不限制处理，
// 版本 1 的未决提议与票数作为本地候选恢复，旧轮候选详情无记录。
//
// 交易池容量（Config.PoolCapacity，0 表示不限制）只统计排队与等待投票的交易。
// 池满时全新交易只能挤出未被未决候选引用的排队交易中费用最低（同费取标识字典序
// 最大）的一笔，且仅当新交易费用更高、或费用相同且标识更小时成功；否则以
// ReasonPoolFull 拒绝且不留历史。被挤出的交易保留完整内容，状态为 dropped。
//
// 稳定编码规则（跨语言可复现）：
//   - 签名编码 SigningBytes：前缀 "consensus-lab-tx-v1\n" 后接 canonical JSON
//     （UTF-8、无空白、字段按名字典序）：
//     {"content":<base64>,"expiry":<uint64>,"fee":<uint64>,"sender":<base64>,"sequence":<uint64>}
//     签名为标准 Ed25519。
//   - 交易标识 Transaction.ID：在上述 JSON 上追加 "signature":<base64> 字段（字段按名字典序），
//     对整体取 SHA-256 的十六进制摘要。
//   - 区块标识 BlockID：对 {"round","height","previous_id","transactions"} 的 canonical JSON
//     取 SHA-256 十六进制摘要；transactions 为按提议顺序排列的交易标识（空块为空数组）。
//   - 每轮提议者：SHA-256(seed || big-endian uint64 round) 的前 8 字节大端整数
//     对验证者人数取模。
package consensus

// Ready 表示基线可以运行。
func Ready() bool { return true }

package consensus

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
)

// 交易被拒绝的具体原因。
const (
	// ReasonBadSignature 签名非法或与发送者公钥不匹配。
	ReasonBadSignature = "bad-signature"
	// ReasonExpired 交易在提交时已经到期（到期轮次不大于当前轮次）。
	ReasonExpired = "tx-expired"
	// ReasonOldSequence 交易序号不大于该发送者已确认序号。
	ReasonOldSequence = "sequence-already-confirmed"
	// ReasonDuplicate 池中已有完全相同的交易（同一发送者、同一序号、同一标识）。
	ReasonDuplicate = "duplicate-transaction"
	// ReasonLowFee 池中同发送者同序号已有交易，但新交易费用没有严格更高。
	ReasonLowFee = "fee-not-higher"
	// ReasonPoolFull 交易池已满，且新交易不足以挤出任何可淘汰的排队交易。
	ReasonPoolFull = "pool-full"
	// ReasonNotValidator 投票者不在验证者名单内。
	ReasonNotValidator = "not-validator"
	// ReasonWrongRound 投票轮次与当前轮次不一致。
	ReasonWrongRound = "wrong-round"
	// ReasonWrongBlock 投票区块标识与当前提议区块标识不一致。
	ReasonWrongBlock = "wrong-block-id"
	// ReasonNoProposal 当前轮次尚不存在提议。
	ReasonNoProposal = "no-proposal"
	// ReasonAlreadyVoted 该验证者本轮已投过其他候选，不能改投。
	ReasonAlreadyVoted = "already-voted"
	// ReasonUnknownRound 查询的轮次不存在（为 0 或尚未到达）。
	ReasonUnknownRound = "unknown-round"
)

// TxStatus 表示一笔交易相对于本节点当前状态的状态。
type TxStatus string

const (
	// StatusQueued 在交易池中等待打包。
	StatusQueued TxStatus = "queued"
	// StatusProposed 已进入当前轮次提议，等待投票。
	StatusProposed TxStatus = "proposed"
	// StatusConfirmed 已被某个确认块包含。
	StatusConfirmed TxStatus = "confirmed"
	// StatusReplaced 在交易池中被同发送者同序号、费用严格更高的交易替换。
	StatusReplaced TxStatus = "replaced"
	// StatusExpired 在进入新轮次时因到期轮次不大于当前轮次而失效。
	StatusExpired TxStatus = "expired"
	// StatusDropped 在交易池满时被费用更高的新交易挤出。
	StatusDropped TxStatus = "dropped"
)

// DropReasonPoolCapacity 是交易被挤出交易池时记录的原因：池容量限制。
const DropReasonPoolCapacity = "pool-capacity"

// Transaction 是一笔带 Ed25519 签名的交易。
type Transaction struct {
	// Sender 发送者公钥（Ed25519 原始 32 字节公钥）。
	Sender []byte `json:"sender"`
	// Sequence 正整数序号。
	Sequence uint64 `json:"sequence"`
	// Content 交易内容，可为任意字节。
	Content []byte `json:"content"`
	// Fee 非负整数费用。
	Fee uint64 `json:"fee"`
	// Expiry 到期轮次：进入不小于该值的轮次时交易失效。
	Expiry uint64 `json:"expiry"`
	// Signature 对 SigningBytes 的 Ed25519 签名。
	Signature []byte `json:"signature"`
}

// signDoc 是签名与稳定编码使用的规范结构。字段按名字典序声明，
// Go 的 JSON 编码按结构体字段顺序输出，故序列化结果即公开的签名编码。
type signDoc struct {
	Content  string `json:"content"`
	Expiry   uint64 `json:"expiry"`
	Fee      uint64 `json:"fee"`
	Sender   string `json:"sender"`
	Sequence uint64 `json:"sequence"`
}

func docFromTx(tx *Transaction) signDoc {
	return signDoc{
		Sender:   base64.StdEncoding.EncodeToString(tx.Sender),
		Sequence: tx.Sequence,
		Content:  base64.StdEncoding.EncodeToString(tx.Content),
		Fee:      tx.Fee,
		Expiry:   tx.Expiry,
	}
}

// SigningBytes 返回交易的公开稳定签名编码：
// canonical JSON（UTF-8、无空白、字段按名字典序）外再包一层固定前缀。
// 任何语言按相同 JSON 规则即可重建并验签。
func SigningBytes(sender ed25519.PublicKey, sequence uint64, content []byte, fee, expiry uint64) []byte {
	tx := &Transaction{Sender: sender, Sequence: sequence, Content: content, Fee: fee, Expiry: expiry}
	raw, _ := json.Marshal(docFromTx(tx))
	out := make([]byte, 0, len("consensus-lab-tx-v1\n")+len(raw))
	out = append(out, []byte("consensus-lab-tx-v1\n")...)
	out = append(out, raw...)
	return out
}

// SigningBytes 返回该交易待签名的字节。
func (tx *Transaction) SigningBytes() []byte {
	return SigningBytes(tx.Sender, tx.Sequence, tx.Content, tx.Fee, tx.Expiry)
}

// Sign 使用发送者私钥填写 Signature。
func (tx *Transaction) Sign(priv ed25519.PrivateKey) {
	tx.Signature = append([]byte(nil), ed25519.Sign(priv, tx.SigningBytes())...)
}

// NewTransaction 构造并用 priv 签名一笔交易。
func NewTransaction(priv ed25519.PrivateKey, sequence uint64, content []byte, fee, expiry uint64) *Transaction {
	pub := priv.Public().(ed25519.PublicKey)
	tx := &Transaction{
		Sender:   append([]byte(nil), pub...),
		Sequence: sequence,
		Content:  append([]byte(nil), content...),
		Fee:      fee,
		Expiry:   expiry,
	}
	tx.Sign(priv)
	return tx
}

// Verify 校验公钥长度、签名长度以及签名是否有效。
func (tx *Transaction) Verify() bool {
	if len(tx.Sender) != ed25519.PublicKeySize || len(tx.Signature) != ed25519.SignatureSize {
		return false
	}
	return ed25519.Verify(ed25519.PublicKey(tx.Sender), tx.SigningBytes(), tx.Signature)
}

// ID 返回交易标识：规范 JSON 字段（含签名）的 SHA-256 十六进制摘要。
// 该规则公开稳定，同字节内容恒有同标识。
func (tx *Transaction) ID() string {
	type txDoc struct {
		Content   string `json:"content"`
		Expiry    uint64 `json:"expiry"`
		Fee       uint64 `json:"fee"`
		Sender    string `json:"sender"`
		Sequence  uint64 `json:"sequence"`
		Signature string `json:"signature"`
	}
	raw, _ := json.Marshal(txDoc{
		Sender:    base64.StdEncoding.EncodeToString(tx.Sender),
		Sequence:  tx.Sequence,
		Content:   base64.StdEncoding.EncodeToString(tx.Content),
		Fee:       tx.Fee,
		Expiry:    tx.Expiry,
		Signature: base64.StdEncoding.EncodeToString(tx.Signature),
	})
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// SenderHex 返回发送者公钥的十六进制串，便于按账户查询。
func (tx *Transaction) SenderHex() string {
	return hex.EncodeToString(tx.Sender)
}

// Vote 是验证者对某一轮某区块标识的投票。
type Vote struct {
	Validator []byte `json:"validator"`
	Round     uint64 `json:"round"`
	BlockID   string `json:"block_id"`
}

// BlockID 是由轮次、前块标识与交易顺序确定的区块标识。
// 对规范文档（轮次、高度、前块标识、按顺序排列的交易标识）取 SHA-256。
func BlockID(round, height uint64, prevID string, txIDs []string) string {
	type blockDoc struct {
		Round        uint64   `json:"round"`
		Height       uint64   `json:"height"`
		PreviousID   string   `json:"previous_id"`
		Transactions []string `json:"transactions"`
	}
	ids := txIDs
	if ids == nil {
		ids = []string{}
	}
	raw, _ := json.Marshal(blockDoc{Round: round, Height: height, PreviousID: prevID, Transactions: ids})
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// Block 是一条连续的确认历史记录。
type Block struct {
	Height     uint64   `json:"height"`
	Round      uint64   `json:"round"`
	ID         string   `json:"id"`
	PreviousID string   `json:"previous_id"`
	TxIDs      []string `json:"tx_ids"`
}

// TxInfo 是一笔交易的查询结果。
type TxInfo struct {
	// ID 交易标识。
	ID string
	// Status 当前状态。
	Status TxStatus
	// Tx 交易内容（历史记录中同样保留完整字节）。
	Tx *Transaction
	// BlockHeight 已确认时所在区块高度；其他状态为 0。
	BlockHeight uint64
	// BlockID 已确认时所在区块标识。
	BlockID string
	// ReplacedBy 已替换时的新交易标识。
	ReplacedBy string
	// DropReason 被挤出时的原因（pool-capacity）；其他状态为空。
	DropReason string
	// DropRound 被挤出发生的轮次；其他状态为 0。
	DropRound uint64
	// Note 仅用于待处理交易："waiting-vote"（已提议，等待投票）或 "waiting-pack"（池内，等待打包）。
	Note string
}

// AccountInfo 是按账户查询的结果。
type AccountInfo struct {
	Sender string
	// ConfirmedSequence 已确认序号，初值为 0。
	ConfirmedSequence uint64
	// Pending 该账户全部待处理交易（池内排队 + 已提议），按序号升序。
	Pending []*TxInfo
	// Gap 因序号缺口等待时，最早缺少的序号；无缺口为 0。
	Gap uint64
}

// RejectError 描述一次提交或投票被拒绝的具体原因。
type RejectError struct {
	Reason string
	Detail string
}

func (e *RejectError) Error() string {
	if e.Detail == "" {
		return e.Reason
	}
	return fmt.Sprintf("%s: %s", e.Reason, e.Detail)
}

func reject(reason, format string, args ...any) error {
	return &RejectError{Reason: reason, Detail: fmt.Sprintf(format, args...)}
}

