590	// RegisterResult 是候选登记结果。
591	type RegisterResult struct {
592		// BlockID 候选区块标识（沿用稳定区块标识编码）。
593		BlockID string
594		// Existing 为 true 时表示相同交易列表此前已登记，本次返回同一候选并保留已有票数。
595		Existing bool
596	}
