5	// 回归保障：同一发送者、同一未确认序号的排队交易被连续加费替换时，
6	// 每一次替换都是独立的一步，历史查询能沿替换关系逐步看清过程。
7	// 本文件沿用既有 Go 库入口（Submit/Tx/Account/Propose）与既有拒绝原因
8	// （fee-not-higher、duplicate-transaction），不引入任何新行为，
9	// 只锁定这些既有结果：替换关联只指向“下一次”接受的交易，不会跨步改指；
10	// 历史交易内容、费用、到期轮次与签名原样保留，且不带确认块信息；
11	// 替换不推进轮次、不增加确认高度、不重新占用池容量。
12	
13	// 三笔同发送者同序号、标识与内容均可区分的交易依次替换（费用 1 -> 5 -> 9）。
14	// 重点是第二次替换之后：原交易的替换关联仍指向第一次接受的新交易，
15	// 中间那笔的关联指向最后接受的交易，更早的关联不能跨步改指最后一笔。
16	func TestReplaceChainKeepsStepByStepHistory(t *testing.T) {
17		keys := genKeys(t, 4)
18		n, _ := newTestNode(t, keys, 10)
19	
20		// 原交易与两笔费用依次严格提高的替换交易：同发送者同序号，
21		// 内容不同因此标识不同，占用的是同一个待处理位置。
22		orig := NewTransaction(keys[0].priv, 1, []byte("chain-orig"), 1, 100)
23		mid := NewTransaction(keys[0].priv, 1, []byte("chain-mid"), 5, 100)
24		last := NewTransaction(keys[0].priv, 1, []byte("chain-last"), 9, 100)
25		origID, midID, lastID := orig.ID(), mid.ID(), last.ID()
26		if origID == midID || midID == lastID || origID == lastID {
27			t.Fatal("test setup: distinct contents must yield distinct ids")
28		}
29		// 同账户序号 3 的排队交易制造缺口 2，用于验证替换不改变缺口。
30		gapTx := NewTransaction(keys[0].priv, 3, []byte("chain-gap"), 7, 100)
31	
32		res, err := n.Submit(orig)
33		if err != nil {
34			t.Fatal(err)
35		}
36		if res.TxID != origID || res.ReplacedID != "" || res.EvictedID != "" {
37			t.Fatalf("first submit result = %+v, want fresh accept of %s", res, origID)
38		}
39		if _, err := n.Submit(gapTx); err != nil {
40			t.Fatal(err)
41		}
42	
43		// 第一次替换：返回本次接受的标识与刚被替换的原交易标识。
44		res, err = n.Submit(mid)
45		if err != nil {
46			t.Fatal(err)
47		}
48		if res.TxID != midID || res.ReplacedID != origID || res.EvictedID != "" {
49			t.Fatalf("first replacement result = %+v, want accept %s replacing %s", res, midID, origID)
50		}
51	
52		// 第二次替换：刚被替换的是中间那笔，不是原交易。
53		res, err = n.Submit(last)
54		if err != nil {
55			t.Fatal(err)
56		}
57		if res.TxID != lastID || res.ReplacedID != midID || res.EvictedID != "" {
58			t.Fatalf("second replacement result = %+v, want accept %s replacing %s", res, lastID, midID)
59		}
60	
61		// 替换不推进当前轮次、不增加确认高度。
62		if n.CurrentRound() != 1 || n.Height() != 0 {
63			t.Fatalf("round/height = %d/%d, want 1/0; replacement must not advance the chain",
64				n.CurrentRound(), n.Height())
65		}
66		if blk, ok := n.LatestBlock(); ok {
67			t.Fatalf("replacement must not confirm a block, got %+v", blk)
68		}
69	
70		// 原交易：仍显示 replaced，替换关联指向第一次接受的新交易，
71		// 不能跨步直接改指最后一笔；不带任何确认块信息；内容原样保留。
72		origInfo, err := n.Tx(origID)
73		if err != nil {
74			t.Fatal(err)
75		}
76		if origInfo.Status != StatusReplaced || origInfo.ReplacedBy != midID {
77			t.Fatalf("orig record = status %s replacedBy %s, want replaced/%s (must not skip to %s)",
78				origInfo.Status, origInfo.ReplacedBy, midID, lastID)
79		}
80		if origInfo.BlockHeight != 0 || origInfo.BlockID != "" {
81			t.Fatalf("replaced history must not carry block info: %+v", origInfo)
82		}
83		assertTxMatches(t, origInfo.Tx, orig)
84	
85		// 中间那笔：同样显示 replaced，关联指向最后接受的交易。
86		midInfo, err := n.Tx(midID)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if midInfo.Status != StatusReplaced || midInfo.ReplacedBy != lastID {
91			t.Fatalf("mid record = status %s replacedBy %s, want replaced/%s",
92				midInfo.Status, midInfo.ReplacedBy, lastID)
93		}
94		if midInfo.BlockHeight != 0 || midInfo.BlockID != "" {
95			t.Fatalf("replaced history must not carry block info: %+v", midInfo)
96		}
97		assertTxMatches(t, midInfo.Tx, mid)
98	
99		// 最新交易：排队等待打包，没有替换关联，也不带确认块信息。
100		lastInfo, err := n.Tx(lastID)
101		if err != nil {
102			t.Fatal(err)
103		}
104		if lastInfo.Status != StatusQueued || lastInfo.ReplacedBy != "" ||
105			lastInfo.BlockHeight != 0 || lastInfo.BlockID != "" {
106			t.Fatalf("latest record wrong: %+v, want queued with no links", lastInfo)
107		}
108		assertTxMatches(t, lastInfo.Tx, last)
109	
110		// 账户查询在该序号上只列出最新交易：queued + waiting-pack；
111		// 已确认序号仍为 0，序号 3 的排队交易不变，缺口仍为 2。
112		acct := n.Account(keys[0].pub)
113		if acct.ConfirmedSequence != 0 || acct.Gap != 2 || len(acct.Pending) != 2 {
114			t.Fatalf("account wrong after chained replacement: %+v", acct)
115		}
116		p1 := acct.Pending[0]
117		if p1.ID != lastID || p1.Status != StatusQueued || p1.Note != "waiting-pack" {
118			t.Fatalf("pending entry for replaced sequence = %+v, want latest %s queued/waiting-pack",
119				p1, lastID)
120		}
121		p3 := acct.Pending[1]
122		if p3.ID != gapTx.ID() || p3.Status != StatusQueued || p3.Note != "waiting-pack" {
123			t.Fatalf("unrelated pending entry changed: %+v", p3)
124		}
125	}
126	
127	// 原交易与另一笔不同发送者的排队交易恰好占满交易池后，连续两次加费替换
128	// 仍都能成功：替换不新占位置，被挤出标识为空，另一笔交易的内容、状态与
129	// 账户待处理结果不变；已替换的历史交易不重新占用池容量。
130	func TestReplaceChainInFullPoolKeepsCapacityAndOthers(t *testing.T) {
131		keys := genKeys(t, 4)
132		n, _ := newTestNodeCap(t, keys, 10, 2)
133	
134		// 容量 2：keys[0] 的原交易与 keys[1] 的排队交易恰好占满。
135		orig := NewTransaction(keys[0].priv, 1, []byte("full-orig"), 1, 100)
136		other := NewTransaction(keys[1].priv, 1, []byte("full-other"), 50, 100)
137		for _, tx := range []*Transaction{orig, other} {
138			if _, err := n.Submit(tx); err != nil {
139				t.Fatal(err)
140			}
141		}
142		if got := n.st.poolSize(); got != 2 {
143			t.Fatalf("test setup: pool size = %d, want exactly full at 2", got)
144		}
145		entriesBefore := len(n.st.Entries)
146	
147		// 第一次替换：满池也成功，不挤出任何交易。
148		r1 := NewTransaction(keys[0].priv, 1, []byte("full-r1"), 5, 100)
149		res, err := n.Submit(r1)
150		if err != nil {
151			t.Fatalf("first replacement in full pool must succeed: %v", err)
152		}
153		if res.TxID != r1.ID() || res.ReplacedID != orig.ID() || res.EvictedID != "" {
154			t.Fatalf("first replacement result = %+v, want replace %s with empty evicted id", res, orig.ID())
155		}
156		if got := n.st.poolSize(); got != 2 {
157			t.Fatalf("pool size after first replacement = %d, want 2 (replaced history must not occupy capacity)", got)
158		}
159	
160		// 第二次替换：同样成功，被挤出标识仍为空。
161		r2 := NewTransaction(keys[0].priv, 1, []byte("full-r2"), 9, 100)
162		res, err = n.Submit(r2)
163		if err != nil {
164			t.Fatalf("second replacement in full pool must succeed: %v", err)
165		}
166		if res.TxID != r2.ID() || res.ReplacedID != r1.ID() || res.EvictedID != "" {
167			t.Fatalf("second replacement result = %+v, want replace %s with empty evicted id", res, r1.ID())
168		}
169	
170		// 替换不推进轮次、不增加确认高度；两段历史都保留但不占容量。
171		if n.CurrentRound() != 1 || n.Height() != 0 {
172			t.Fatalf("round/height = %d/%d, want 1/0", n.CurrentRound(), n.Height())
173		}
174		if got := n.st.poolSize(); got != 2 {
175			t.Fatalf("pool size after second replacement = %d, want 2", got)
176		}
177		if got := len(n.st.Entries); got != entriesBefore+2 {
178			t.Fatalf("entries = %d, want %d (two replacement histories kept)", got, entriesBefore+2)
179		}
180	
181		// 替换链逐步可查：orig -> r1 -> r2，r2 排队。
182		if info, _ := n.Tx(orig.ID()); info.Status != StatusReplaced || info.ReplacedBy != r1.ID() {
183			t.Fatalf("orig record = %+v, want replaced by %s", info, r1.ID())
184		}
185		if info, _ := n.Tx(r1.ID()); info.Status != StatusReplaced || info.ReplacedBy != r2.ID() {
186			t.Fatalf("r1 record = %+v, want replaced by %s", info, r2.ID())
187		}
188		r2Info, err := n.Tx(r2.ID())
189		if err != nil {
190			t.Fatal(err)
191		}
192		if r2Info.Status != StatusQueued || r2Info.ReplacedBy != "" {
193			t.Fatalf("r2 record = %+v, want queued with no link", r2Info)
194		}
195		assertTxMatches(t, r2Info.Tx, r2)
196	
197		// 另一发送者的排队交易内容、状态原样，账户待处理结果不变。
198		otherInfo, err := n.Tx(other.ID())
199		if err != nil {
200			t.Fatal(err)
201		}
202		if otherInfo.Status != StatusQueued || otherInfo.ReplacedBy != "" ||
203			otherInfo.DropReason != "" || otherInfo.DropRound != 0 {
204			t.Fatalf("other tx changed by replacements: %+v", otherInfo)
205		}
206		assertTxMatches(t, otherInfo.Tx, other)
207		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{other.ID(): "waiting-pack"})
208		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{r2.ID(): "waiting-pack"})
209	}
210	
211	// 连续替换之后、尚未产生提议且最新交易仍排队时的两种拒绝：
212	// 费用等于或低于当前交易的新标识替换尝试返回 fee-not-higher 且不留历史；
213	// 按原始内容与签名重投已被替换的交易返回 duplicate-transaction。
214	// 拒绝后既有替换关联、最新排队交易与其他账户交易均保持原样，
215	// 随后合法的更高费用交易仍可正常替换。
216	func TestReplaceChainRejectionsLeaveHistoryIntact(t *testing.T) {
217		keys := genKeys(t, 4)
218		n, _ := newTestNode(t, keys, 10)
219	
220		// 另一发送者的排队交易：拒绝操作不得波及。
221		other := NewTransaction(keys[1].priv, 1, []byte("bystander"), 3, 100)
222		if _, err := n.Submit(other); err != nil {
223			t.Fatal(err)
224		}
225	
226		// 建立 orig -> mid -> last 的替换链（费用 1 -> 5 -> 9）。
227		orig := NewTransaction(keys[0].priv, 1, []byte("rej-orig"), 1, 100)
228		mid := NewTransaction(keys[0].priv, 1, []byte("rej-mid"), 5, 100)
229		last := NewTransaction(keys[0].priv, 1, []byte("rej-last"), 9, 100)
230		for _, tx := range []*Transaction{orig, mid, last} {
231			if _, err := n.Submit(tx); err != nil {
232				t.Fatal(err)
233			}
234		}
235		origID, midID, lastID := orig.ID(), mid.ID(), last.ID()
236	
237		// 场景前提：尚未产生提议，最新交易仍在排队。
238		if _, ok := n.Proposal(); ok {
239			t.Fatal("test setup: no proposal must exist yet")
240		}
241		if info, _ := n.Tx(lastID); info.Status != StatusQueued {
242			t.Fatalf("test setup: latest status = %s, want queued", info.Status)
243		}
244		entriesBefore := len(n.st.Entries)
245	
246		// 拒绝一：标识不同、费用与当前交易相等（9）的替换尝试。
247		equalFee := NewTransaction(keys[0].priv, 1, []byte("rej-equal"), 9, 100)
248		if equalFee.ID() == lastID {
249			t.Fatal("test setup: equal-fee tx must have a distinct id")
250		}
251		res, err := n.Submit(equalFee)
252		if reason(err) != ReasonLowFee {
253			t.Fatalf("equal-fee replacement reason = %v, want %s", err, ReasonLowFee)
254		}
255		if res != nil {
256			t.Fatalf("rejected submit must return nil result, got %+v", res)
257		}
258		if _, err := n.Tx(equalFee.ID()); reason(err) != ReasonUnknownTx {
259			t.Fatalf("equal-fee tx lookup = %v, want %s (no history kept)", err, ReasonUnknownTx)
260		}
261	
262		// 拒绝二：标识不同、费用低于当前交易（6 < 9，虽高于中间那笔的 5）的替换尝试。
263		// 费用比较只针对当前排队交易，与任何历史交易无关。
264		lowerFee := NewTransaction(keys[0].priv, 1, []byte("rej-lower"), 6, 100)
265		res, err = n.Submit(lowerFee)
266		if reason(err) != ReasonLowFee {
267			t.Fatalf("lower-fee replacement reason = %v, want %s", err, ReasonLowFee)
268		}
269		if res != nil {
270			t.Fatalf("rejected submit must return nil result, got %+v", res)
271		}
272		if _, err := n.Tx(lowerFee.ID()); reason(err) != ReasonUnknownTx {
273			t.Fatalf("lower-fee tx lookup = %v, want %s (no history kept)", err, ReasonUnknownTx)
274		}
275	
276		// 拒绝三：按原始内容与签名重投已被替换的原交易。
277		replayOrig := NewTransaction(keys[0].priv, 1, []byte("rej-orig"), 1, 100)
278		if replayOrig.ID() != origID {
279			t.Fatalf("test setup: byte-identical replay id %s != original %s", replayOrig.ID(), origID)
280		}
281		res, err = n.Submit(replayOrig)
282		if reason(err) != ReasonDuplicate {
283			t.Fatalf("replay of replaced orig reason = %v, want %s", err, ReasonDuplicate)
284		}
285		if res != nil {
286			t.Fatalf("rejected submit must return nil result, got %+v", res)
287		}
288	
289		// 拒绝四：按原始内容与签名重投已被替换的中间交易。
290		replayMid := NewTransaction(keys[0].priv, 1, []byte("rej-mid"), 5, 100)
291		if replayMid.ID() != midID {
292			t.Fatalf("test setup: byte-identical replay id %s != mid %s", replayMid.ID(), midID)
293		}
294		res, err = n.Submit(replayMid)
295		if reason(err) != ReasonDuplicate {
296			t.Fatalf("replay of replaced mid reason = %v, want %s", err, ReasonDuplicate)
297		}
298		if res != nil {
299			t.Fatalf("rejected submit must return nil result, got %+v", res)
300		}
301	
302		// 拒绝不留副作用：不新增记录、不推进轮次、不增加确认高度。
303		if got := len(n.st.Entries); got != entriesBefore {
304			t.Fatalf("entries changed %d -> %d after rejections", entriesBefore, got)
305		}
306		if n.CurrentRound() != 1 || n.Height() != 0 {
307			t.Fatalf("round/height = %d/%d, want 1/0 after rejections", n.CurrentRound(), n.Height())
308		}
309	
310		// 已有替换关联保持原样：orig -> mid -> last，不跨步改指。
311		origInfo, err := n.Tx(origID)
312		if err != nil {
313			t.Fatal(err)
314		}
315		if origInfo.Status != StatusReplaced || origInfo.ReplacedBy != midID {
316			t.Fatalf("orig record after rejections = %+v, want replaced/%s", origInfo, midID)
317		}
318		assertTxMatches(t, origInfo.Tx, orig)
319		midInfo, err := n.Tx(midID)
320		if err != nil {
321			t.Fatal(err)
322		}
323		if midInfo.Status != StatusReplaced || midInfo.ReplacedBy != lastID {
324			t.Fatalf("mid record after rejections = %+v, want replaced/%s", midInfo, lastID)
325		}
326		assertTxMatches(t, midInfo.Tx, mid)
327	
328		// 最新排队交易与其他账户交易均保持原样。
329		lastInfo, err := n.Tx(lastID)
330		if err != nil {
331			t.Fatal(err)
332		}
333		if lastInfo.Status != StatusQueued || lastInfo.ReplacedBy != "" {
334			t.Fatalf("latest record after rejections = %+v, want queued with no link", lastInfo)
335		}
336		assertTxMatches(t, lastInfo.Tx, last)
337		otherInfo, err := n.Tx(other.ID())
338		if err != nil {
339			t.Fatal(err)
340		}
341		if otherInfo.Status != StatusQueued {
342			t.Fatalf("bystander tx changed: %+v", otherInfo)
343		}
344		assertTxMatches(t, otherInfo.Tx, other)
345		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{lastID: "waiting-pack"})
346		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{other.ID(): "waiting-pack"})
347	
348		// 随后提交合法的更高费用交易：仍按既有规则正常替换最新交易。
349		final := NewTransaction(keys[0].priv, 1, []byte("rej-final"), 10, 100)
350		res, err = n.Submit(final)
351		if err != nil {
352			t.Fatalf("valid higher-fee tx must still replace after rejections: %v", err)
353		}
354		if res.TxID != final.ID() || res.ReplacedID != lastID || res.EvictedID != "" {
355			t.Fatalf("final replacement result = %+v, want accept %s replacing %s", res, final.ID(), lastID)
356		}
357		// 链条延长一步：last -> final；更早的关联仍不跨步改指。
358		if info, _ := n.Tx(lastID); info.Status != StatusReplaced || info.ReplacedBy != final.ID() {
359			t.Fatalf("last record = %+v, want replaced/%s", info, final.ID())
360		}
361		if info, _ := n.Tx(midID); info.ReplacedBy != lastID {
362			t.Fatalf("mid link rewired to %s, want still %s", info.ReplacedBy, lastID)
363		}
364		if info, _ := n.Tx(origID); info.ReplacedBy != midID {
365			t.Fatalf("orig link rewired to %s, want still %s", info.ReplacedBy, midID)
366		}
367		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{final.ID(): "waiting-pack"})
368	}
